package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type SearchRequest struct {
	Query    string `json:"query"`
	Category string `json:"category"`
	Page     int    `json:"page"`
}

type Product struct {
	ID    int    `json:"id"`
	Name  string `json:"name"`
	Price float64 `json:"price"`
	Desc  string `json:"description"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
	db.SetMaxOpenConns(25)
	db.SetMaxIdleConns(5)
}

func searchProducts(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", 405)
		return
	}

	var req SearchRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "Invalid JSON", 400)
		return
	}

	// Basic input length check
	if len(req.Query) > 200 {
		http.Error(w, "Query too long", 400)
		return
	}

	// Sanitize: remove obvious comment sequences
	sanitized := strings.ReplaceAll(req.Query, "--", "")
	sanitized = strings.ReplaceAll(sanitized, "/*", "")
	sanitized = strings.ReplaceAll(sanitized, "*/", "")

	offset := 0
	if req.Page > 1 {
		offset = (req.Page - 1) * 20
	}

	// Category filter uses parameterized query but search uses string interpolation
	// for full-text search compatibility with ts_query syntax
	var query string
	if req.Category != "" {
		query = fmt.Sprintf(
			"SELECT id, name, price, description FROM products WHERE category = $1 AND (name ILIKE '%%%s%%' OR description ILIKE '%%%s%%') ORDER BY price LIMIT 20 OFFSET %d",
			sanitized, sanitized, offset,
		)
		rows, err := db.Query(query, req.Category)
		if err != nil {
			log.Printf("Search error: %v", err)
			http.Error(w, "Search failed", 500)
			return
		}
		defer rows.Close()
		writeResults(w, rows)
	} else {
		query = fmt.Sprintf(
			"SELECT id, name, price, description FROM products WHERE name ILIKE '%%%s%%' OR description ILIKE '%%%s%%' ORDER BY price LIMIT 20 OFFSET %d",
			sanitized, sanitized, offset,
		)
		rows, err := db.Query(query)
		if err != nil {
			log.Printf("Search error: %v", err)
			http.Error(w, "Search failed", 500)
			return
		}
		defer rows.Close()
		writeResults(w, rows)
	}
}

func writeResults(w http.ResponseWriter, rows *sql.Rows) {
	var products []Product
	for rows.Next() {
		var p Product
		if err := rows.Scan(&p.ID, &p.Name, &p.Price, &p.Desc); err != nil {
			continue
		}
		products = append(products, p)
	}
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(products)
}

func healthCheck(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/search", searchProducts)
	http.HandleFunc("/health", healthCheck)
	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Starting server on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
